{
  "_doc": "Manual operativo de conexion MQTT directa al sistema Enki SIN scripts. Incluye datos de conexion, patrones de topics, envelope canonico, secuencia completa para iniciar y mantener una conversacion (project.list → conversation.create → conversation.send → escuchar response), y shapes reales de los 5 eventos canonicos del flujo chat (chat.message.saved, chat.context.enriched, chat.prompt.ready, ai.chat.response, ai.chat.failed) extraidos del codigo. Permite conectarse desde cualquier cliente MQTT (mqttx, MQTT Explorer, librerias en otros lenguajes) sin depender de los helpers JS del repo. Tambien recoge el patron generico request/response correlacionado por request_id, secuencias canonicas adicionales para operaciones de dominio, probes de diagnostico forense aplicables cuando los helpers se quedan cortos, catalogo de eventos read-only seguros para clientes externos, errores clasicos al construir clientes ad-hoc, implementacion de referencia minima en Node.js, y relacion explicita con otros contratos del sistema.",
  "id": "manual-mqtt-conexion-directa",
  "version": "1.0.0",
  "creada": "2026-05-20",
  "tipo": "manual_operativo",
  "conexion": {
    "url": "wss://enki-ai.online/mqtt",
    "protocolo": "MQTT v3.1.1 sobre WebSocket Secure",
    "host": "enki-ai.online",
    "puerto": 443,
    "path": "/mqtt",
    "tls": true,
    "auth": "ninguna — el broker no exige usuario/password. El token EXPORT_TOKEN solo aplica al endpoint HTTP /api/conversation-export, no al MQTT.",
    "client_id": "Cualquier string unico por cliente (ej: 'mqttx-1234', 'mi-app-abc'). Si se repite con otro cliente conectado, el broker cierra la conexion anterior.",
    "keepalive_recomendado_seg": 60,
    "ejemplo_clientes_compatibles": [
      "MQTT Explorer",
      "mqttx (CLI o desktop)",
      "mqtt.js (Node)",
      "paho-mqtt (Python)",
      "MQTT.fx",
      "wscat para inspeccion raw"
    ]
  },
  "topics": {
    "_doc": "Dos familias de topics: (a) eventos del bus interno con patron core/<core_id>/events/<event_type_with_slashes>, (b) UI request/response con patron ui/request/<dominio>/<accion> y ui/response/<request_id>.",
    "patron_eventos_bus": {
      "publish": "core/*/events/<event_type_con_slashes>",
      "subscribe": "core/+/events/<event_type_con_slashes>",
      "regla_conversion_event_type_a_topic": "Los puntos del event_type se convierten en slashes. Ejemplo: 'chat.message.saved' → 'chat/message/saved'. El topic completo: 'core/+/events/chat/message/saved'.",
      "wildcards": {
        "+": "comodin un nivel — usar siempre en subscribe en el segundo segmento (core_id variable)",
        "#": "comodin recursivo — usar al final si quieres todos los sub-eventos"
      }
    },
    "patron_ui_request_response": {
      "publish_request": "ui/request/<dominio>/<accion>",
      "subscribe_response": "ui/response/<request_id_del_payload>",
      "ejemplos": [
        "ui/request/conversation/create",
        "ui/request/conversation/send",
        "ui/response/<uuid_generado_por_ti>"
      ]
    },
    "topics_utiles_para_debug": {
      "todos_los_eventos_del_bus": "core/+/events/#",
      "todas_las_responses_ui": "ui/response/+",
      "solo_chat_flow": [
        "core/+/events/chat/message/saved",
        "core/+/events/chat/context/enriched",
        "core/+/events/chat/prompt/ready",
        "core/+/events/ai/chat/response",
        "core/+/events/ai/chat/failed"
      ],
      "solo_subsistema_recetario": [
        "core/+/events/receta/+",
        "core/+/events/ingrediente/+/+",
        "core/+/events/fs/+/+"
      ]
    }
  },
  "envelope_canonico_del_bus": {
    "_doc": "Shape estandar de TODOS los eventos publicados en topics 'core/*/events/...'. El payload del MQTT (despues del JSON.stringify) es exactamente este shape.",
    "shape": {
      "event_id": "<uuid v4 — identificador unico del evento>",
      "event_type": "<nombre.canonico.del.evento (con puntos)>",
      "timestamp": "<ISO 8601: '2026-05-20T12:00:00.000Z'>",
      "source": {
        "core_id": "<string identificando el origen del evento>"
      },
      "data": {
        "request_id": "<uuid v4 — solo cuando aplica request/response correlation>",
        "...": "<resto del payload especifico del evento>"
      },
      "metadata": "{}"
    },
    "correlation": "El campo data.request_id correlaciona pares request/response. El campo data.correlation_id propaga la cadena causal por todo el flujo (lo lleva chat-io en chat.message.saved y se preserva en cada evento downstream del subsistema)."
  },
  "envelope_ui_request_response": {
    "_doc": "Shape estandar para topics 'ui/request/...' y 'ui/response/...'. NO usa envelope del bus — es directo.",
    "shape_request": {
      "request_id": "<uuid v4>",
      "data": {
        "...": "<payload especifico de la accion>"
      }
    },
    "shape_response": {
      "request_id": "<mismo uuid del request>",
      "success": "<true | false>",
      "data": "<resultado de la accion>",
      "error": "<presente solo si success=false>"
    }
  },
  "secuencia_iniciar_conversacion": {
    "_doc": "Pasos para crear conversacion y mandar primer mensaje desde MQTT directo, sin scripts.",
    "paso_1_resolver_project_id": {
      "objetivo": "Obtener el UUID del proyecto a partir de su nombre (si no lo tienes).",
      "publish_topic": "core/*/events/project/list/request",
      "publish_payload": {

