const fs=require('fs');
const lines=fs.readFileSync('/tmp/audit-carta-flow.jsonl','utf8').split('\n').filter(Boolean);
const evs=lines.map(l=>{try{return JSON.parse(l)}catch(e){return null}}).filter(Boolean);
console.log('=== PRIMER Y ULTIMO EVENTO ===');
console.log('primer:', evs[0]._captured_at, evs[0].event_type);
console.log('ultimo:', evs[evs.length-1]._captured_at, evs[evs.length-1].event_type);
console.log();
console.log('=== PROJECT.* EN ORDEN ===');
evs.filter(e=>e.event_type.startsWith('project.')).forEach(e=>{
  const s = e.source && (e.source.core_id || e.source.module || JSON.stringify(e.source));
  const d = e.data ? JSON.stringify(e.data).slice(0,140) : '';
  console.log(e._captured_at.slice(11,23), e.event_type, '| src:', s, '| data:', d);
});
console.log();
console.log('=== CHAT/CONVERSATION/AI EVENTOS (cualquier nombre) ===');
const chatlike = evs.filter(e=>/chat|conversation|message|ai\./i.test(e.event_type));
console.log('count:', chatlike.length);
chatlike.slice(0,20).forEach(e=>{
  console.log(e._captured_at.slice(11,23), e.event_type);
});
"

