43	  const acc = [];
44	  function walk(dir, depth) {
45	    if (depth > 6 || !fs.existsSync(dir)) return;
46	    for (const name of fs.readdirSync(dir)) {
47	      if (name === 'node_modules' || name === '_archived' || name === '_legacy' || name.startsWith('.')) continue;
