'use strict';

const mqtt = require('mqtt');
const crypto = require('crypto');
const readline = require('readline');

function parseArgs(argv) {
  const flags = {
    dryRun: false,
    yes: false,
    keep: [],
    only: [],
    broker: process.env.AUDIT_BROKER || 'wss://enki-ai.online/mqtt',
    timeout: 10000,
    pause: 500,
  };
  for (let i = 0; i < argv.length; i++) {
