modules/pizzepos/carta-marketing/carta-marketing.blueprint.json
modules/pizzepos/carta-scheduler/carta-scheduler.blueprint.json"

for f in $BLUEPRINTS; do
  git checkout --theirs "$f" && echo "  theirs  $f"
done

echo
echo "=== STEP 2: module.json -> ours ==="
MJ="modules/pizzepos/carta-design/module.json
modules/pizzepos/carta-digital/module.json
modules/pizzepos/carta-impresion/module.json
modules/pizzepos/carta-manager/module.json
modules/pizzepos/carta-scheduler/module.json"

for f in $MJ; do
  git checkout --ours "$f" && echo "  ours    $f"
done

echo
echo "=== STEP 3: aplicar replacements de paths a blueprints ==="
node -e "
const fs = require('fs');
const files = process.argv.slice(1);
let total = 0;
for (const f of files) {
  let c = fs.readFileSync(f, 'utf8');
  const before = c;
  // Quitar /storage/ prefix de paths en publishAndWait fs.*, paths_relativos, etc.
  // Conservadora: solo sustituye literal '/storage/' (con barra delante) que aparece
  // en strings de pseudocodigo y metadata.
  c = c.replace(/(['\"])\/storage\//g, '\$1');
  if (c !== before) {
    fs.writeFileSync(f, c);
    const n = (before.match(/(['\"])\/storage\//g) || []).length;
    total += n;
    console.log('  patched', n, 'paths in', f);
  } else {
    console.log('  no changes', f);
  }
}
console.log('---total replacements:', total);
" $BLUEPRINTS
echo
echo "=== STEP 4: check JSON validity ==="
for f in $BLUEPRINTS $MJ; do
  node -e "JSON.parse(require('fs').readFileSync('$f','utf8'))" && echo "  OK   $f" || echo "  BAD  $f"
done

