+    }
+    if (orphans.length === 0) {
+      console.error('\n[cleanup] nada que borrar. Fin.');
+      client.end();
+      return;
+    }
+    if (!flags.yes) {
+      const ans = await confirmInteractive(
+        `\n[cleanup] CONFIRMA: escribe DELETE para borrar los ${orphans.length} directorios huerfanos: `
+      );
