+        client.end();
+        process.exit(1);
+      }
+    }
+
+    // 5. Borrar uno por uno
+    console.error('\n[cleanup] borrando huerfanos via fs.delete.request...');
+    const results = { ok: 0, failed: 0 };
+    for (const d of orphans) {
+      const targetPath = 'data/projects/' + d;
+      try {
+        const t0 = Date.now();
