const mqtt = require('mqtt'); const crypto = require('crypto');
const VAPERS_ALHAMA = '5f8ac209-8113-445f-961a-8e82b7f7002d';

const c = mqtt.connect('wss://enki-ai.online/mqtt', { clientId: 'fetch-carta-'+Date.now(), reconnectPeriod: 0 });

function uiReq(domain, action, data) {
  return new Promise((resolve, reject) => {
    const rid = crypto.randomUUID();
    const topic = 'ui/response/' + rid;
    const onMsg = (t, m) => {
      if (t !== topic) return;
      c.removeListener('message', onMsg);
      c.unsubscribe(topic);
      clearTimeout(tm);
      try { resolve(JSON.parse(m.toString())); } catch(e) { reject(e); }
    };
    const tm = setTimeout(() => { c.removeListener('message', onMsg); reject(new Error('timeout '+topic)); }, 15000);
    c.on('message', onMsg);
    c.subscribe(topic, err => { if (err) reject(err); else c.publish('ui/request/' + domain + '/' + action, JSON.stringify({ request_id: rid, data })); });
  });
}

function busReq(eventType, responseType, payload) {
  return new Promise((resolve, reject) => {
    const rid = crypto.randomUUID();
    const subTopic = 'core/+/events/' + responseType.replace(/\\./g,'/');
    const reqTopic = 'core/*/events/' + eventType.replace(/\\./g,'/');
    const onMsg = (t, m) => {
      try {
        const env = JSON.parse(m.toString());
        if (env.event_type !== responseType) return;
        if (env.data?.request_id !== rid) return;
        c.removeListener('message', onMsg);
        c.unsubscribe(subTopic);
        clearTimeout(tm);
        resolve(env);
      } catch(e) {}
    };
    const tm = setTimeout(() => { c.removeListener('message', onMsg); reject(new Error('timeout '+responseType)); }, 15000);
    c.on('message', onMsg);
    c.subscribe(subTopic, err => {
      if (err) reject(err);
      else c.publish(reqTopic, JSON.stringify({
        event_id: crypto.randomUUID(), event_type: eventType,
        timestamp: new Date().toISOString(), source: { core_id: 'fetch-carta' },
        data: { request_id: rid, ...payload }, metadata: {}
      }));
    });
  });
}

