    "verdad_paradigma_que_lo_contradice": "event-core exige federacion: soberania en el dominio Y bus como autoridad superior a memoria propia",
    "manifestacion_general": "modulo asume su estado interno es la verdad; desencuentros con el resto los atribuye al resto; se cubre con cache, fallback, lectura disco directa, catch tragador, decision libre sobre campos no especificados"
  },

  "paradigma_forzado": {
    "type": "invariant",
    "name": "el_llm_escribe_contracorriente_de_su_corpus",
    "expression": "corpus_dominante_aprendido === microservicios_autonomos_con_defensa_local; event_core_puro !== corpus_dominante; tendencia_idiomatica > disciplina_leida_al_inicio_de_sesion",
    "consecuencia": "conciencia intelectual del paradigma no impide regresion al escribir; disciplina requiere andamios mecanicos, no narrativos"
  },

  "ModuloEventCore_canonico": {
    "type": "abstract_class",
    "name": "ModuloEventCore",
    "extends": "BaseModule",
    "abstract_methods": {
      "onLoad(context)": "register subscribers; initialize state by replaying canonical events of own domain from bus; never read disk directly",
      "onUnload()": "release resources without persisting outside bus"
    },
    "concrete_invariants": [
      "this.cache === null || this.cache instanceof CacheIncremental",
      "for each publish(event): event.payload is complete before publish",
      "for each handler(event): event.source.module is read explicit, no fallback to active",
      "all I/O passes through bus events; no direct fs.* or db.* calls outside whitelist [filesystem, database-manager, project-manager]"
    ],
    "forbidden_patterns": [
      {
        "type": "forbidden_pattern",
        "pattern_regex": "this\\._?cache\\s*=\\s*new Map",
        "reason": "cache defensiva propia duplica autoridad del bus",
        "alternative_pseudo_code": [
          "// estado solo en memoria volatil reconstruida al onLoad",
          "// o consulta sincrona via this.bus.publishAndWait(...)"
        ]
      },
