      "creencia_aprendida_corpus": "fs.readdir y fs.readFile son APIs estandar; usarlas es eficiente",
      "verdad_paradigma_que_la_contradice": "filesystem es modulo dueño del scope; bus es la unica forma de mantener autoridad",
      "patron_codigo_a_evitar_regex": [
        "require\\(['\"]fs['\"]\\)",
        "await fs\\.readdir",
        "await fs\\.readFile",
        "await fs\\.writeFile"
      ],
      "patron_codigo_canonico_pseudo_code": [
        "const list = await this.bus.publishAndWait('fs.list.request', { project_id, path })",
        "const content = await this.bus.publishAndWait('fs.read.request', { project_id, path })"
