            "role": {"type": "Role", "value": null, "access": "protected"},
            "isActive": {"type": "boolean", "value": true, "access": "public"}
        },
        "methods": {
            assignRole(role: Role): void {
                IF role IS NULL THEN
                    THROW "Role cannot be null"
                END IF
                SET this.role TO role
                LOG "Role assigned: " + role.name
            },
            hasPermission(permission: string): boolean {
                IF this.role IS NULL THEN
                    RETURN false
                END IF
                RETURN this.role.permissions CONTAINS permission
            }
        }
    }

    OBJECT Role {
        "properties": {
            "name": {"type": "string", "value": null, "access": "public"},
            "permissions": {"type": "list", "value": [], "access": "public"}
        },
        "methods": {
            addPermission(permission: string): void {
                IF NOT this.permissions CONTAINS permission THEN
                    APPEND permission TO this.permissions
                END IF
            }
        }
    }

}"
  }
}
