            "action": "call",
            "target": "this.bus.publishAndWait",
            "value": "('producto.guardado', producto)"
          },
          {
            "action": "return",
            "target": null,
            "condition": null,
            "value": "write_result"
          }
        ],
        "returns": "object"
      }
