    "version": "0.1.0",
    "creado": "2026-06-03",
    "language": "es-ES",
    "supersedes": null,
    "intencion": "v0.1.0 del lenguaje Fiel. Sintesis del experimento 7-LLMs (Kimi/Claude_puro/ChatGPT/DeepSeek/Grok/Manus/Gemini) usando Fiel (Claude puro) como base + cuatro piezas aditivas: (1) enforcedTendencies por clase (DeepSeek CanonLang), (2) severidad enum en tendencias (Kimi ContraForma), (3) auto_audit detecta plagio + markdown + over-engineering (Kimi ContraForma), (4) bus_connection como primitiva nativa (Gemini KanonJSON). Caso de uso: canonizar contratos arquitectonicos del repo Enki event-core.",
    "origen_empirico": {
      "experimento": "arquitectura/decisiones/propuestas/_prompt-disenyo-lenguaje-3coops-v0.1.json",
      "respuestas_LLM_sintetizadas": [
        "Fiel (Claude puro, base)",
        "CanonLang (DeepSeek, aporta enforcedTendencies)",
        "ContraForma (Kimi, aporta severidad + auto_audit ampliado)",
        "KanonJSON (Gemini, aporta bus_connection)",
        "CanonLang_v2 (Grok, convergente con CanonLang)",
        "LLM-SPEC-LANG (ChatGPT, descartado por over-engineering)",
        "CognitoScript (Manus, no descargable, conceptual)"
      ]
    }
  },

  "name": "Fiel",

  "philosophy_breve": "JSON estricto como contenedor sintactico. OOP minimal como modelado conceptual. Pseudocodigo natural acotado por shape como logica algoritmica. Tendencias del LLM inyectadas como primitivas de primer nivel. Auto-auditoria como protocolo obligatorio antes de devolver output. Sin meta-niveles, sin compiladores, sin extensiones por dominio. Lo justo para canonizar contratos arquitectonicos sin que el LLM reintroduzca drift.",

  "componentes": [
    {
      "id": "code",
      "descripcion_corta": "JSON estricto. Cada string tiene maxLength o pattern regex. Sin prosa libre fuera de campos _doc cortos."
    },
    {
      "id": "OOP",
      "descripcion_corta": "Modelado conceptual via abstract_class, concrete_class, properties, methods, constructor, extends, invariants, forbidden_patterns. Herencia vertical explicita o null."
    },
    {
      "id": "pseudo_code",
      "descripcion_corta": "Cada paso es objeto JSON con shape { action, target, condition, value }. NO strings raw multilinea. NO sintaxis libre."
    }
  ],

  "primitivas_canonicas": [
    {
      "name": "AbstractClass",
      "type": "primitiva_oop",
      "shape_json": {
        "type": "literal_string \"abstract_class\"",
        "name": "string matches /^[A-Z][A-Za-z0-9]*$/",
        "extends": "string | null",
        "properties": "array<Property>",
        "abstract_methods": "object<MethodName, pseudo_code_signature>",
        "concrete_invariants": "array<Invariant>",
        "forbidden_patterns": "array<ForbiddenPattern>",
        "enforcedTendencies": "array<TendenciaId> matches /^T[0-9]+_[a-z_]+$/"
      }
    },
    {
      "name": "ConcreteClass",
      "type": "primitiva_oop",
      "shape_json": {
        "type": "literal_string \"concrete_class\"",
        "name": "string matches /^[A-Z][A-Za-z0-9]*$/",
        "extends": "string | null",
        "properties": "array<Property>",
        "methods": "array<Method>",
        "invariants": "array<Invariant>",
        "forbidden_patterns": "array<ForbiddenPattern>",
        "enforcedTendencies": "array<TendenciaId>"
      }
    },
    {
      "name": "Property",
      "type": "primitiva_oop",
      "shape_json": {
        "type": "literal_string \"property\"",
        "name": "string camelCase",
        "type_expression": "string maxLength 50",
        "visibility": "enum [\"public\", \"private\", \"protected\"]",
        "nullable": "boolean",
        "default": "any | null"
      }
    },
    {
      "name": "Method",
      "type": "primitiva_oop",
      "shape_json": {
        "type": "literal_string \"method\"",
        "name": "string matches /^[a-z][A-Za-z0-9]*$/",
        "visibility": "enum [\"public\", \"private\", \"protected\"]",
        "params": "array<Param>",
        "returns": "type_expression",
        "pseudo_code": "array<PseudoStep> maxItems 30",
        "throws": "array<error_code>"
      }
    },
    {
      "name": "Constructor",
      "type": "primitiva_oop",
      "shape_json": {
        "type": "literal_string \"constructor\"",
        "params": "array<Param>",
        "pseudo_code": "array<PseudoStep> maxItems 15",
        "invariants_after": "array<Invariant>"
      }
    },
    {
      "name": "Param",
      "type": "primitiva_oop",
      "shape_json": {
        "name": "string camelCase",
        "type_expression": "string maxLength 50",
        "required": "boolean",
        "default": "any | null"
      }
    },
    {
      "name": "Invariant",
      "type": "primitiva_logica",
      "shape_json": {
        "type": "literal_string \"invariant\"",
        "expression": "string maxLength 200",
        "applies_to": "ClassName | MethodName | \"global\""
      }
    },
    {
      "name": "PseudoStep",
      "type": "primitiva_logica",
      "shape_json": {
        "type": "literal_string \"pseudo_step\"",
        "action": "enum [\"emit\", \"listen\", \"store\", \"fetch\", \"validate\", \"transform\", \"branch\", \"loop\", \"assign\", \"call\", \"return\", \"throw\", \"log\", \"comment\"]",
        "target": "string | null",
        "condition": "string | null",
        "value": "any | null"
      },
      "constraints": [
        "action es enum cerrado de 14 valores",
        "target es identificador del subject del action (event_type para emit/listen, var_name para assign/store, etc.)",
        "condition es expresion booleana evaluable mentalmente; null si action incondicional",
        "value es el dato literal o expresion; null si action no produce valor"
      ]
    },
    {
      "name": "ForbiddenPattern",
      "type": "primitiva_logica",
      "shape_json": {
        "type": "literal_string \"forbidden_pattern\"",
        "pattern_regex": "string PCRE valida",
        "reason": "string maxLength 200",
        "alternative_pseudo_code": "array<PseudoStep> maxItems 10",
        "severidad": "enum [\"error\", \"warning\", \"info\"]"
      }
    },
    {
      "name": "Tendencia",
      "type": "primitiva_meta",
      "shape_json": {
        "type": "literal_string \"tendencia\"",
        "id": "string matches /^T[0-9]+_[a-z_]+$/",
        "creencia_aprendida_corpus": "string maxLength 200 sin conectores discursivos",
        "verdad_paradigma_que_la_contradice": "string maxLength 200 sin conectores discursivos",
        "patron_codigo_a_evitar_regex": "array<string PCRE>",
        "patron_codigo_canonico_pseudo_code": "array<PseudoStep>",
        "severidad": "enum [\"error\", \"warning\", \"info\"]",
        "caso_testigo_repo": "FileLineReference"
      }
    },
    {
      "name": "BusConnection",
      "type": "primitiva_dominio",
      "shape_json": {
        "type": "literal_string \"bus_connection\"",
        "publishes": "array<EventDeclaration>",
        "listens": "array<EventDeclaration>",
        "publishes_and_waits": "array<EventPair>",
        "constraints": "array<Invariant>"
      },
      "_doc": "Captura la interaccion modulo-bus como ciudadano de primer nivel. Reemplaza la mezcla habitual de publishes/subscribes desperdigada por methods. Heredado de KanonJSON (Gemini)."
    },
    {
      "name": "EventDeclaration",
      "type": "primitiva_dominio",
      "shape_json": {
        "event_type": "string matches /^[a-z][a-z0-9-]*\\.[a-z][a-z0-9_]*\\.[a-z]+$/",
        "shape_ref": "string maxLength 200",
        "consumed_by": "array<string> | null",
        "produces_response_event": "string | null"
      }
    },
    {
      "name": "EventPair",
      "type": "primitiva_dominio",
      "shape_json": {
        "request_event": "EventDeclaration",
        "response_event": "EventDeclaration",
        "timeout_ms_default": "integer >= 1000"
      }
    },
    {
      "name": "FileLineReference",
      "type": "primitiva_meta",
      "shape_json": {
        "archivo": "string matches /^[a-z0-9_/.-]+\\.[a-z]+$|^audit_[0-9-]+_[a-z_]+$/",
        "linea_aprox": "integer >= 0",
        "drift_id": "string matches /^drift_[a-z_]+$/"
      }
    }
  ],

