python3 -c "
import json, re
with open('arquitectura/decisiones/propuestas/_fiel-v0.1.0.json') as f:
    doc = json.load(f)

conectores = re.compile(r'\b(aunque|salvo que|en general|sin embargo|por otro lado)\b', re.IGNORECASE)
long_words = re.compile(r'[a-z]{31,}')

violations = []
def walk(node, path):
    if isinstance(node, dict):
        for k, v in node.items():
            walk(v, f'{path}.{k}')
    elif isinstance(node, list):
        for i, v in enumerate(node):
            walk(v, f'{path}[{i}]')
    elif isinstance(node, str):
        # ignorar pattern_regex que pueden contener literal 'aunque' como regex
        if 'pattern_regex' in path or 'patron_codigo_a_evitar' in path or 'forbidden_patterns_meta' in path:
            return
        if conectores.search(node):
            violations.append(f'CONECTOR {path}: {node[:80]}')
        if long_words.search(node):
            m = long_words.search(node)
            violations.append(f'LONG_WORD {path}: {m.group()}')

walk(doc, '\$')
if violations:
    print('Violaciones:')
    for v in violations[:20]:
        print('  -', v)
else:
    print('Self-audit OK: sin conectores ni palabras > 30 chars (fuera de campos regex)')
"

