    "fuente_cocinado_ref": "arquitectura/decisiones/propuestas/_arranque-modulo-event-core-disciplina.json#tajada_3",
    "caso_testigo_ref": "arquitectura/decisiones/propuestas/_pizzepos-productos-disciplina-via-notario.json",
    "plasmado_por": "agente notario tajada 3",
    "intencion": "Canoniza dos AbstractClass hijas de ModuloEventCore que diferencian aggregate root de vista. Aggregate es dueno del dominio: mantiene estado canonico en memoria reconstruido por replay y publica mutaciones del dominio propio. Vista es proyeccion derivada: mantiene cache local hidratada por eventos del aggregate ajeno y NO publica mutaciones del dominio del aggregate. La mezcla de las dos posturas produce drift T1 + T5 + T7 simultaneos.",
    "supersedes_nota": "tajada 3 del arranque modulo-event-core-disciplina. Deriva del contrato padre ModuloEventCore. No supersede ningun contrato previo; abre la distincion aggregate-vista que CLAUDE.md menciona implicitamente en seccion 'Puntos de extension modulares' sin formalizarla."
  },

  "abstract_classes": [
    {
      "type": "abstract_class",
      "name": "AggregateRoot",
      "extends": "ModuloEventCore",
      "_doc": "Modulo dueno de un dominio. Mantiene estado canonico del agregado en memoria reconstruido en onLoad por replay de eventos canonicos del bus. Publica mutaciones del dominio propio (creada, actualizada, eliminada). Persiste a disco via filesystem (no fs directo). Otros modulos leen el dominio via publishes del aggregate o via consultas publishAndWait.",
      "properties": [
        { "type": "property", "name": "dominioName", "type_expression": "string camelCase", "visibility": "protected", "nullable": false, "default": null },
        { "type": "property", "name": "estadoAgregado", "type_expression": "Map<entityId, Entity> | object", "visibility": "protected", "nullable": false, "default": "new Map()" },
        { "type": "property", "name": "persistenceScope", "type_expression": "enum [project, system]", "visibility": "protected", "nullable": false, "default": "project" }
      ],
      "abstract_methods": {
        "onLoad(context)": "registra subscribers de eventos canonicos del dominio propio; reconstruye estadoAgregado por replay desde filesystem via fs.read.request del scope declarado",
        "publishMutacion(verbo, payload)": "publica evento <dominio>.<entidad>.<verbo> con payload completo despues de aterrizar el cambio en disco; verbo del enum canonico [creada, actualizada, eliminada]",
        "persistAgregado(entityId)": "emite fs.write.request con shape canonico y espera fs.write.response antes de publish de mutacion"
      },
      "concrete_invariants": [
        { "type": "invariant", "expression": "this.dominioName es el unico nombre que aparece en el prefijo de los eventos que this publica", "applies_to": "AggregateRoot" },
        { "type": "invariant", "expression": "for each handler(event): event no pertenece al dominio de otro aggregate; o si pertenece, this no muta estadoAgregado en base a el", "applies_to": "global" },
        { "type": "invariant", "expression": "this.estadoAgregado se reconstruye en onLoad por replay desde el scope declarado, nunca por subscribe a eventos de otros modulos", "applies_to": "AggregateRoot" },
        { "type": "invariant", "expression": "publish de <dominio>.<entidad>.<verbo> ocurre despues de fs.write.response confirmada", "applies_to": "publishMutacion" },
        { "type": "invariant", "expression": "ningun campo persistido se sobreescribe en el replay; el disco es la verdad", "applies_to": "onLoad" }
      ],
      "forbidden_patterns": [
        {
          "type": "forbidden_pattern",
          "pattern_regex": "on(?!Load|Unload)[A-Z]\\w*\\s*\\([^)]*\\)\\s*\\{[\\s\\S]{0,500}?this\\.estadoAgregado",
          "reason": "handler de evento ajeno que muta el estadoAgregado convierte el aggregate en vista contaminada del dominio del emisor",
          "alternative_pseudo_code": [
            { "type": "pseudo_step", "action": "comment", "target": null, "condition": null, "value": "si el aggregate necesita un dato ajeno: publishAndWait al aggregate dueno, sin cachear el resultado en estadoAgregado" }
          ],
          "severidad": "error"
        },
        {
          "type": "forbidden_pattern",
          "pattern_regex": "this\\.publish\\(['\"][a-z-]+\\.[a-z_]+\\.(creada|actualizada|eliminada)['\"]",
          "reason": "publish de mutacion canonica con prefijo de dominio que no es this.dominioName invade dominio ajeno",
          "alternative_pseudo_code": [
            { "type": "pseudo_step", "action": "validate", "target": "event_prefix", "condition": "event_prefix === this.dominioName", "value": null },
            { "type": "pseudo_step", "action": "throw", "target": "INVALID_INPUT", "condition": "prefix_mismatch", "value": "publish de dominio ajeno prohibido" }
          ],
          "severidad": "error"
        },
        {
          "type": "forbidden_pattern",
          "pattern_regex": "this\\.\\w+PerProject\\s*=\\s*new Map[\\s\\S]{0,2000}?on[A-Z]\\w*\\s*\\([^)]*\\)\\s*\\{[\\s\\S]{0,500}?this\\.\\w+PerProject\\.(set|get)",
          "reason": "cache PerProject rehidratada por handlers de eventos ajenos es vista materializada disfrazada de aggregate",
          "alternative_pseudo_code": [
            { "type": "pseudo_step", "action": "comment", "target": null, "condition": null, "value": "decidir: si el modulo es vista, declarar extends Vista y mover publishes de mutacion a la clase Vista que prohibe publicar mutaciones; si es aggregate, eliminar handlers de eventos ajenos que rehidratan cache" }
          ],
          "severidad": "error"
        }
      ],
      "enforcedTendencies": [
        "T1_cache_defensiva",
        "T2_fallback_silencioso_identidad",
        "T5_sobreescribir_estado_al_recargar",
        "T7_handoff_prematuro"
      ]
    },
    {
      "type": "abstract_class",
      "name": "Vista",
      "extends": "ModuloEventCore",
      "_doc": "Modulo proyeccion derivada. Mantiene cache local en memoria hidratada por eventos canonicos de aggregates ajenos. NO publica mutaciones de dominio ajeno. Puede publicar eventos del dominio propio si tiene dominio propio acotado (ej: comandero publica comandero.item_agregado de su buffer propio, NO publica producto.actualizado del catalogo). La cache es volatil y se reconstruye solicitando snapshot al aggregate dueno en onLoad via publishAndWait o evento <dominio_ajeno>.config.solicitada.",
      "properties": [
        { "type": "property", "name": "cacheLocal", "type_expression": "Map<entityId, EntitySnapshot>", "visibility": "protected", "nullable": false, "default": "new Map()" },
        { "type": "property", "name": "aggregatesObservados", "type_expression": "array<dominioName>", "visibility": "protected", "nullable": false, "default": "[]" },
        { "type": "property", "name": "dominioPropio", "type_expression": "string | null", "visibility": "protected", "nullable": true, "default": null }
      ],
      "abstract_methods": {
        "onLoad(context)": "registra subscribers de eventos canonicos de aggregatesObservados; solicita snapshot inicial via publishAndWait al aggregate dueno o via evento <dominio>.config.solicitada",
        "hidratarDesdeEvento(event)": "actualiza cacheLocal a partir del payload completo del evento del aggregate ajeno; nunca lee disco para verificar",
        "publishDominioPropio(verbo, payload)": "publica eventos del dominioPropio si esta declarado; verbo del enum canonico"
      },
      "concrete_invariants": [
        { "type": "invariant", "expression": "this.cacheLocal es volatil; reconstruible en onLoad sin acceso a disco", "applies_to": "Vista" },
        { "type": "invariant", "expression": "for each publish(event): event.prefix === this.dominioPropio OR this.dominioPropio === null y this no publica mutacion alguna", "applies_to": "global" },
        { "type": "invariant", "expression": "for each handler(event): this.cacheLocal se actualiza con event.payload completo; sin lectura de disco para validar", "applies_to": "hidratarDesdeEvento" },
        { "type": "invariant", "expression": "this.aggregatesObservados declara explicito de que dominios la vista cachea snapshot", "applies_to": "Vista" },
        { "type": "invariant", "expression": "ningun handler de evento ajeno publica un evento <dominio_ajeno>.<entidad>.<verbo>", "applies_to": "global" }
      ],
