    "plasmado_por": "agente notario tercera prueba",
    "intencion": "Canoniza la propagacion del contexto de proyecto (project_id + base_path) entre modulos via bus. Complementa project-identity.contract.json: ese fija quien posee la identidad y el path; este fija como viaja el contexto y cuando se cachea localmente. Cierra el drift de active_project implicito documentado en pizzepos/productos:62 (resolveToActiveProject) que itera el Map y devuelve el primero con datos."
  },

  "type": "abstract_class",
  "name": "PropagacionContextoProyecto",
  "extends": "ModuloEventCore",

  "properties": [
    { "type": "property", "name": "activeProjectCache", "type_expression": "Map<projectId, ProjectContext>", "visibility": "protected", "nullable": false, "default": "new Map()" },
    { "type": "property", "name": "pendingProjectRequests", "type_expression": "Map<requestId, PendingRequest>", "visibility": "protected", "nullable": false, "default": "new Map()" },
    { "type": "property", "name": "propagationProtocol", "type_expression": "enum [suscripcion_a_project_activated, request_para_no_activos]", "visibility": "protected", "nullable": false, "default": "suscripcion_a_project_activated" }
  ],

  "abstract_methods": {
    "onProjectActivated(event)": "cachea event.data.base_path indexado por event.data.project_id; nunca recalcula slug desde event.data.name",
    "onProjectDeactivated(event)": "elimina entrada del cache para event.data.project_id; sin fallback al primer proyecto restante",
    "resolveProjectContext(projectId)": "devuelve ProjectContext del cache si esta presente; si no, throw INVALID_INPUT; nunca itera el Map buscando otro project_id con datos"
  },

  "concrete_invariants": [
    { "type": "invariant", "expression": "this.activeProjectCache.get(projectId) devuelve ProjectContext con base_path absoluto persistido en project.activated", "applies_to": "PropagacionContextoProyecto" },
    { "type": "invariant", "expression": "for each operation(projectId): si !this.activeProjectCache.has(projectId) entonces throw INVALID_INPUT sin iteracion del Map", "applies_to": "global" },
    { "type": "invariant", "expression": "for each handler(event): event.data.project_id leido explicito desde el payload, sin fallback a primer activo", "applies_to": "global" },
    { "type": "invariant", "expression": "base_path se lee de event.data.base_path; nunca se computa con _slugify(event.data.name) ni con path.join cwd", "applies_to": "onProjectActivated" },
    { "type": "invariant", "expression": "project.get.request solo se publica para project_id no presente en cache local AND fuera del camino caliente", "applies_to": "global" }
  ],

  "forbidden_patterns": [
    {
      "type": "forbidden_pattern",
      "pattern_regex": "resolveTo\\w*Fallback|resolveToActive\\w*",
      "reason": "fallback silencioso al primer proyecto con datos convierte modulo multi-tenant en single-tenant accidental; caso testigo modules/pizzepos/productos/index.js:62",
      "alternative_pseudo_code": [
        { "type": "pseudo_step", "action": "branch", "target": "if_not_cache_has", "condition": "!this.activeProjectCache.has(projectId)", "value": null },
        { "type": "pseudo_step", "action": "throw", "target": "INVALID_INPUT", "condition": null, "value": "project_id no resuelto: ${projectId}" }
      ],
      "severidad": "error"
    },
    {
      "type": "forbidden_pattern",
      "pattern_regex": "for\\s*\\(.*of this\\.\\w+\\.keys\\(\\)\\)\\s*\\{?\\s*return",
      "reason": "iteracion del Map buscando el primer proyecto con datos enmascara desincronizacion entre llamador y cache local",
      "alternative_pseudo_code": [
        { "type": "pseudo_step", "action": "branch", "target": "if_not_cache_has", "condition": "!this.activeProjectCache.has(projectId)", "value": null },
        { "type": "pseudo_step", "action": "throw", "target": "INVALID_INPUT", "condition": null, "value": "project_id no resuelto" }
