      "type": "forbidden_pattern",
      "pattern_regex": "this\\.activeProjectId\\s*=|this\\._activeProject\\s*=",
      "reason": "single active project implicito; project-manager soporta activeProjectIds Set (multi-active), asumir un unico activo viola la realidad del sistema",
      "alternative_pseudo_code": [
        { "type": "pseudo_step", "action": "store", "target": "this.activeProjectCache", "condition": null, "value": "set(project_id, { base_path, name })" },
        { "type": "pseudo_step", "action": "comment", "target": null, "condition": null, "value": "cardinalidad N: cada operacion lleva su project_id explicito" }
      ],
      "severidad": "error"
