        { "type": "pseudo_step", "action": "call", "target": "this.bus.publishAndWait", "condition": null, "value": "{ eventType: 'project.get.request', payload: { request_id, project_id } }" }
      ],
      "severidad": "warning"
    }
  ],

  "bus_connection": {
    "type": "bus_connection",
